export const appointments = pgTable(
  "appointments",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    patient_id: uuid().notNull(),
    provider_id: uuid().notNull(),
    location_id: uuid().notNull(),
    appointment_type_id: uuid().notNull(),
    source_request_id: uuid(),
    starts_at: timestamp({ withTimezone: true, mode: "string" }).notNull(),
    ends_at: timestamp({ withTimezone: true, mode: "string" }).notNull(),
    duration_minutes: integer().notNull(),
    buffer_before_minutes: integer().notNull(),
    buffer_after_minutes: integer().notNull(),
    reserved_from: timestamp({ withTimezone: true, mode: "string" }).notNull(),
    reserved_until: timestamp({ withTimezone: true, mode: "string" }).notNull(),
    status: text().default("scheduled").notNull(),
    reason: text(),
    version: bigint({ mode: "number" }).default(1).notNull(),
    created_at: timestamp({ withTimezone: true, mode: "string" }).defaultNow().notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" }).defaultNow().notNull(),
    created_by: uuid().notNull(),
    updated_by: uuid().notNull(),
    request_workflow_managed: boolean().default(false).notNull(),
  },
  (table) => [
    uniqueIndex("appointments_active_request_idx")
      .using("btree", table.source_request_id.asc().nullsLast().op("uuid_ops"))
      .where(sql`((source_request_id IS NOT NULL) AND (status <> 'cancelled'::text))`),
    index("appointments_interval_idx").using(
      "gist",
      sql`tstzrange(starts_at, ends_at, '[)'::text)`,
    ),
    index("appointments_location_start_idx").using(
      "btree",
      table.location_id.asc().nullsLast().op("timestamptz_ops"),
      table.starts_at.asc().nullsLast().op("uuid_ops"),
      table.id.asc().nullsLast().op("timestamptz_ops"),
    ),
    index("appointments_patient_start_idx").using(
      "btree",
      table.patient_id.asc().nullsLast().op("timestamptz_ops"),
      table.starts_at.asc().nullsLast().op("timestamptz_ops"),
      table.id.asc().nullsLast().op("timestamptz_ops"),
    ),
    index("appointments_provider_start_idx").using(
      "btree",
      table.provider_id.asc().nullsLast().op("uuid_ops"),
      table.starts_at.asc().nullsLast().op("uuid_ops"),
      table.id.asc().nullsLast().op("timestamptz_ops"),
    ),
    index("appointments_source_request_idx").using(
      "btree",
      table.source_request_id.asc().nullsLast().op("uuid_ops"),
      table.patient_id.asc().nullsLast().op("uuid_ops"),
    ),
    index("appointments_type_idx").using(
      "btree",
      table.appointment_type_id.asc().nullsLast().op("uuid_ops"),
    ),
    foreignKey({
      columns: [table.location_id],
      foreignColumns: [scheduling_locations.id],
      name: "appointments_location_id_fkey",
    }).onDelete("restrict"),
    foreignKey({
      columns: [table.appointment_type_id],
      foreignColumns: [appointment_types.id],
      name: "appointments_appointment_type_id_fkey",
    }).onDelete("restrict"),
    foreignKey({
      columns: [table.patient_id, table.source_request_id],
      foreignColumns: [patient_request_links.patient_id, patient_request_links.request_id],
      name: "appointments_source_request_id_patient_id_fkey",
    }).onDelete("set null"),
    foreignKey({
      columns: [table.patient_id],
      foreignColumns: [patients.id],
      name: "appointments_patient_id_fkey",
    }).onDelete("restrict"),
    foreignKey({
      columns: [table.provider_id],
      foreignColumns: [scheduling_providers.id],
      name: "appointments_provider_id_fkey",
    }).onDelete("restrict"),
    unique("appointments_id_patient_id_key").on(table.id, table.patient_id),
    check("appointments_starts_at_check", sql`CHECK (isfinite(starts_at`),
    check("appointments_check", sql`isfinite(ends_at) AND (ends_at > starts_at)`),
    check(
      "appointments_duration_minutes_check",
      sql`(duration_minutes >= 1) AND (duration_minutes <= 1440)`,
    ),
    check(
      "appointments_buffer_before_minutes_check",
      sql`(buffer_before_minutes >= 0) AND (buffer_before_minutes <= 720)`,
    ),
    check(
      "appointments_buffer_after_minutes_check",
      sql`(buffer_after_minutes >= 0) AND (buffer_after_minutes <= 720)`,
    ),
    check("appointments_reserved_from_check", sql`CHECK (isfinite(reserved_from`),
    check("appointments_reserved_until_check", sql`CHECK (isfinite(reserved_until`),
    check(
      "appointments_status_check",
      sql`status = ANY (ARRAY['scheduled'::text, 'checked_in'::text, 'completed'::text, 'no_show'::text, 'cancelled'::text])`,
    ),
    check(
      "appointments_reason_check",
      sql`(reason = btrim(reason)) AND ((char_length(reason) >= 1) AND (char_length(reason) <= 500))`,
    ),
    check(
      "appointments_version_check",
      sql`(version >= 1) AND (version <= '9007199254740991'::bigint)`,
    ),
    check(
      "appointments_check1",
      sql`ends_at = (starts_at + make_interval(mins => duration_minutes))`,
    ),
    check(
      "appointments_check2",
      sql`reserved_from = (starts_at - make_interval(mins => buffer_before_minutes))`,
    ),
    check(
      "appointments_check3",
      sql`reserved_until = (ends_at + make_interval(mins => buffer_after_minutes))`,
    ),
  ],
);

