export const patient_clinical_records = pgTable(
  "patient_clinical_records",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    patient_id: uuid().notNull(),
    appointment_id: uuid(),
    record_kind: text().notNull(),
    title: text().notNull(),
    service_date: date(),
    note_text: text(),
    document_source: text(),
    document_reference: text(),
    document_sha256: text(),
    status: text().default("draft").notNull(),
    amends_id: uuid(),
    amends_version: bigint({ mode: "number" }),
    version: bigint({ mode: "number" }).default(1).notNull(),
    author_id: uuid().notNull(),
    author_email: text().notNull(),
    signed_by: uuid(),
    signed_by_email: text(),
    signed_at: timestamp({ withTimezone: true, mode: "string" }),
    error_reason: text(),
    created_at: timestamp({ withTimezone: true, mode: "string" }).defaultNow().notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" }).defaultNow().notNull(),
    updated_by: uuid().notNull(),
  },
  (table) => [
    index("patient_clinical_records_amends_idx").using(
      "btree",
      table.amends_id.asc().nullsLast().op("uuid_ops"),
      table.patient_id.asc().nullsLast().op("uuid_ops"),
    ),
    index("patient_clinical_records_appointment_idx").using(
      "btree",
      table.appointment_id.asc().nullsLast().op("uuid_ops"),
      table.patient_id.asc().nullsLast().op("uuid_ops"),
    ),
    uniqueIndex("patient_clinical_records_one_amendment_idx")
      .using("btree", table.amends_id.asc().nullsLast().op("uuid_ops"))
      .where(sql`((amends_id IS NOT NULL) AND (status <> 'entered_in_error'::text))`),
    index("patient_clinical_records_patient_idx").using(
      "btree",
      table.patient_id.asc().nullsLast().op("uuid_ops"),
      table.created_at.desc().nullsFirst().op("uuid_ops"),
      table.id.asc().nullsLast().op("timestamptz_ops"),
    ),
    foreignKey({
      columns: [table.patient_id],
      foreignColumns: [patients.id],
      name: "patient_clinical_records_patient_id_fkey",
    }).onDelete("restrict"),
    foreignKey({
      columns: [table.patient_id, table.appointment_id],
      foreignColumns: [appointments.id, appointments.patient_id],
      name: "patient_clinical_records_appointment_id_patient_id_fkey",
    }).onDelete("restrict"),
    foreignKey({
      columns: [table.patient_id, table.amends_id],
      foreignColumns: [table.id, table.patient_id],
      name: "patient_clinical_records_amends_id_patient_id_fkey",
    }).onDelete("restrict"),
    unique("patient_clinical_records_id_patient_id_key").on(table.id, table.patient_id),
    check(
      "patient_clinical_records_record_kind_check",
      sql`record_kind = ANY (ARRAY['note'::text, 'document_reference'::text])`,
    ),
    check(
      "patient_clinical_records_title_check",
      sql`(title = btrim(title)) AND ((char_length(title) >= 1) AND (char_length(title) <= 120))`,
    ),
    check(
      "patient_clinical_records_service_date_check",
      sql`(service_date >= '0001-01-01'::date) AND isfinite(service_date)`,
    ),
    check(
      "patient_clinical_records_document_sha256_check",
      sql`document_sha256 ~ '^[a-f0-9]{64}$'::text`,
    ),
    check(
      "patient_clinical_records_status_check",
      sql`status = ANY (ARRAY['draft'::text, 'signed'::text, 'entered_in_error'::text])`,
    ),
    check(
      "patient_clinical_records_version_check",
      sql`(version >= 1) AND (version <= '9007199254740991'::bigint)`,
    ),
    check(
      "patient_clinical_records_error_reason_check",
      sql`(error_reason = btrim(error_reason)) AND ((char_length(error_reason) >= 1) AND (char_length(error_reason) <= 500))`,
    ),
    check(
      "patient_clinical_records_check",
      sql`((amends_id IS NULL) AND (amends_version IS NULL)) OR ((amends_id IS NOT NULL) AND (amends_version IS NOT NULL) AND ((amends_version >= 1) AND (amends_version <= '9007199254740991'::bigint)))`,
    ),
    check("patient_clinical_records_check1", sql`amends_id IS DISTINCT FROM id`),
    check(
      "patient_clinical_records_check2",
      sql`((record_kind = 'note'::text) AND (note_text IS NOT NULL) AND (char_length(note_text) <= 20000) AND (document_source IS NULL) AND (document_reference IS NULL) AND (document_sha256 IS NULL)) OR ((record_kind = 'document_reference'::text) AND (note_text IS NULL) AND (document_source IS NOT NULL) AND (document_source = btrim(document_source)) AND ((char_length(document_source) >= 1) AND (char_length(document_source) <= 120)) AND (document_reference IS NOT NULL) AND (document_reference = btrim(document_reference)) AND ((char_length(document_reference) >= 1) AND (char_length(document_reference) <= 200)))`,
    ),
    check(
      "patient_clinical_records_check3",
      sql`((signed_at IS NULL) AND (signed_by IS NULL) AND (signed_by_email IS NULL)) OR ((signed_at IS NOT NULL) AND (signed_by IS NOT NULL) AND (signed_by_email IS NOT NULL) AND (signed_by = author_id))`,
    ),
    check(
      "patient_clinical_records_check4",
      sql`((status = 'draft'::text) AND (signed_at IS NULL) AND (error_reason IS NULL)) OR ((status = 'signed'::text) AND (signed_at IS NOT NULL) AND (error_reason IS NULL) AND ((record_kind <> 'note'::text) OR (note_text ~ '[^[:space:]]'::text))) OR ((status = 'entered_in_error'::text) AND (error_reason IS NOT NULL))`,
    ),
  ],
);

