export const provider_time_exceptions = pgTable(
  "provider_time_exceptions",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    provider_id: uuid().notNull(),
    location_id: uuid(),
    kind: text().notNull(),
    starts_at: timestamp({ withTimezone: true, mode: "string" }).notNull(),
    ends_at: timestamp({ withTimezone: true, mode: "string" }).notNull(),
    reason: text(),
  },
  (table) => [
    index("provider_time_exceptions_location_idx").using(
      "btree",
      table.location_id.asc().nullsLast().op("uuid_ops"),
    ),
    index("provider_time_exceptions_provider_idx").using(
      "btree",
      table.provider_id.asc().nullsLast().op("timestamptz_ops"),
      table.starts_at.asc().nullsLast().op("timestamptz_ops"),
    ),
    foreignKey({
      columns: [table.provider_id],
      foreignColumns: [scheduling_providers.id],
      name: "provider_time_exceptions_provider_id_fkey",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.location_id],
      foreignColumns: [scheduling_locations.id],
      name: "provider_time_exceptions_location_id_fkey",
    }).onDelete("restrict"),
    check(
      "provider_time_exceptions_kind_check",
      sql`kind = ANY (ARRAY['available'::text, 'unavailable'::text])`,
    ),
    check("provider_time_exceptions_starts_at_check", sql`CHECK (isfinite(starts_at`),
    check("provider_time_exceptions_check", sql`isfinite(ends_at) AND (ends_at > starts_at)`),
    check(
      "provider_time_exceptions_check1",
      sql`(kind <> 'available'::text) OR (location_id IS NOT NULL)`,
    ),
    check(
      "provider_time_exceptions_reason_check",
      sql`reason = ANY (ARRAY['personal'::text, 'conference'::text, 'holiday'::text])`,
    ),
    check(
      "provider_time_exceptions_reason_unavailable",
      sql`(kind = 'unavailable'::text) OR (reason IS NULL)`,
    ),
  ],
);

export const scheduling_changes = pgTable(
  "scheduling_changes",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    entity: text().notNull(),
    entity_id: uuid().notNull(),
    appointment_id: uuid(),
    provider_id: uuid(),
    location_id: uuid(),
    appointment_type_id: uuid(),
    version: bigint({ mode: "number" }).notNull(),
    command: text().notNull(),
    before_record: jsonb(),
    after_record: jsonb().notNull(),
    compensates_change_id: uuid(),
    actor_id: uuid().notNull(),
    actor_email: text().notNull(),
    occurred_at: timestamp({ withTimezone: true, mode: "string" }).defaultNow().notNull(),
    request_id: uuid(),
    request_before: jsonb(),
    request_after_version: bigint({ mode: "number" }),
    request_transition_id: uuid(),
  },
  (table) => [
    index("scheduling_changes_appointment_idx").using(
      "btree",
      table.appointment_id.asc().nullsLast().op("uuid_ops"),
    ),
    index("scheduling_changes_location_idx").using(
      "btree",
      table.location_id.asc().nullsLast().op("uuid_ops"),
    ),
    index("scheduling_changes_occurred_idx").using(
      "btree",
      table.occurred_at.desc().nullsFirst().op("uuid_ops"),
      table.id.desc().nullsFirst().op("uuid_ops"),
    ),
    index("scheduling_changes_provider_idx").using(
      "btree",
      table.provider_id.asc().nullsLast().op("uuid_ops"),
    ),
    index("scheduling_changes_request_idx")
      .using("btree", table.request_id.asc().nullsLast().op("uuid_ops"))
      .where(sql`(request_id IS NOT NULL)`),
    uniqueIndex("scheduling_changes_request_transition_idx")
      .using("btree", table.request_transition_id.asc().nullsLast().op("uuid_ops"))
      .where(sql`(request_transition_id IS NOT NULL)`),
    index("scheduling_changes_type_idx").using(
      "btree",
      table.appointment_type_id.asc().nullsLast().op("uuid_ops"),
    ),
    foreignKey({
      columns: [table.appointment_id],
      foreignColumns: [appointments.id],
      name: "scheduling_changes_appointment_id_fkey",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.provider_id],
      foreignColumns: [scheduling_providers.id],
      name: "scheduling_changes_provider_id_fkey",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.location_id],
      foreignColumns: [scheduling_locations.id],
      name: "scheduling_changes_location_id_fkey",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.appointment_type_id],
      foreignColumns: [appointment_types.id],
      name: "scheduling_changes_appointment_type_id_fkey",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.compensates_change_id],
      foreignColumns: [table.id],
      name: "scheduling_changes_compensates_change_id_fkey",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.request_id],
      foreignColumns: [requests.id],
      name: "scheduling_changes_request_id_fkey",
    }).onDelete("set null"),
    foreignKey({
      columns: [table.request_transition_id],
      foreignColumns: [request_transitions.id],
      name: "scheduling_changes_request_transition_id_fkey",
    }).onDelete("set null"),
    unique("scheduling_changes_entity_entity_id_version_key").on(
      table.entity,
      table.entity_id,
      table.version,
    ),
    unique("scheduling_changes_compensates_change_id_key").on(table.compensates_change_id),
    check(
      "scheduling_changes_version_check",
      sql`(version >= 1) AND (version <= '9007199254740991'::bigint)`,
    ),
    check(
      "scheduling_request_snapshot_check",
      sql`((request_before IS NULL) AND (request_after_version IS NULL) AND (request_transition_id IS NULL)) OR ((request_before IS NOT NULL) AND (jsonb_typeof(request_before) = 'object'::text) AND (request_after_version IS NOT NULL) AND ((request_after_version >= 1) AND (request_after_version <= '9007199254740991'::bigint)) AND (request_before ?& ARRAY['state'::text, 'callAgainAt'::text, 'bookingConfirmedAt'::text, 'appointmentAt'::text, 'closedAt'::text, 'closureReason'::text, 'closureDisposition'::text, 'closureProvenance'::text, 'legacyReviewRequired'::text]))`,
    ),
    check(
      "scheduling_changes_entity_check",
      sql`entity = ANY (ARRAY['provider'::text, 'location'::text, 'appointment_type'::text, 'appointment'::text, 'practice'::text])`,
    ),
    check(
      "scheduling_changes_check",
      sql`((entity = 'appointment'::text) AND (appointment_id IS NOT NULL) AND (appointment_id = entity_id) AND (provider_id IS NULL) AND (location_id IS NULL) AND (appointment_type_id IS NULL)) OR ((entity = 'provider'::text) AND (provider_id IS NOT NULL) AND (provider_id = entity_id) AND (appointment_id IS NULL) AND (location_id IS NULL) AND (appointment_type_id IS NULL)) OR ((entity = 'location'::text) AND (location_id IS NOT NULL) AND (location_id = entity_id) AND (appointment_id IS NULL) AND (provider_id IS NULL) AND (appointment_type_id IS NULL)) OR ((entity = 'appointment_type'::text) AND (appointment_type_id IS NOT NULL) AND (appointment_type_id = entity_id) AND (appointment_id IS NULL) AND (provider_id IS NULL) AND (location_id IS NULL)) OR ((entity = 'practice'::text) AND (appointment_id IS NULL) AND (provider_id IS NULL) AND (location_id IS NULL) AND (appointment_type_id IS NULL))`,
    ),
    check(
      "scheduling_changes_command_check",
      sql`command = ANY (ARRAY['save_provider'::text, 'save_location'::text, 'save_appointment_type'::text, 'book'::text, 'reschedule'::text, 'cancel'::text, 'check_in'::text, 'complete'::text, 'no_show'::text, 'undo'::text, 'add_provider'::text, 'set_provider_profile'::text, 'set_provider_weekly_hours'::text, 'add_time_off'::text, 'remove_time_off'::text, 'set_provider_types'::text, 'reorder_appointment_types'::text, 'set_appointment_type_active'::text, 'delete_appointment_type'::text, 'save_location_details'::text, 'add_location_closure'::text, 'remove_location_closure'::text, 'set_provider_day_hours'::text, 'set_booking_interval'::text, 'retire_provider'::text, 'restore_provider'::text, 'retire_location'::text, 'restore_location'::text])`,
    ),
  ],
);

