export const location_hours = pgTable(
  "location_hours",
  {
    location_id: uuid().notNull(),
    weekday: integer().notNull(),
    open_minute: integer().notNull(),
    close_minute: integer().notNull(),
  },
  (table) => [
    foreignKey({
      columns: [table.location_id],
      foreignColumns: [scheduling_locations.id],
      name: "location_hours_location_id_fkey",
    }).onDelete("cascade"),
    primaryKey({ columns: [table.location_id, table.weekday], name: "location_hours_pkey" }),
    check("location_hours_weekday_check", sql`(weekday >= 0) AND (weekday <= 6)`),
    check("location_hours_open_minute_check", sql`(open_minute >= 0) AND (open_minute <= 1439)`),
    check(
      "location_hours_check",
      sql`((close_minute >= 1) AND (close_minute <= 1440)) AND (close_minute > open_minute)`,
    ),
  ],
);

export const portal_release_states = pgTable(
  "portal_release_states",
  {
    staff_user_id: uuid().notNull(),
    release_id: text().notNull(),
    first_opened_at: timestamp({ withTimezone: true, mode: "string" }).defaultNow().notNull(),
    acknowledged_at: timestamp({ withTimezone: true, mode: "string" }),
    hidden_at: timestamp({ withTimezone: true, mode: "string" }),
    last_viewed_at: timestamp({ withTimezone: true, mode: "string" }).defaultNow().notNull(),
    view_count: integer().default(1).notNull(),
    guide_opened_at: timestamp({ withTimezone: true, mode: "string" }),
    last_guide_opened_at: timestamp({ withTimezone: true, mode: "string" }),
    guide_open_count: integer().default(0).notNull(),
    last_dismissed_at: timestamp({ withTimezone: true, mode: "string" }),
    dismiss_count: integer().default(0).notNull(),
  },
  (table) => [
    foreignKey({
      columns: [table.staff_user_id],
      foreignColumns: [staff_profiles.user_id],
      name: "portal_release_states_staff_user_id_fkey",
    }).onDelete("cascade"),
    primaryKey({
      columns: [table.staff_user_id, table.release_id],
      name: "portal_release_states_pkey",
    }),
    check(
      "portal_release_states_release_id_valid",
      sql`(release_id = btrim(release_id)) AND ((char_length(release_id) >= 1) AND (char_length(release_id) <= 80)) AND (release_id ~ '^[a-z0-9][a-z0-9._-]*$'::text)`,
    ),
    check(
      "portal_release_states_view_count_valid",
      sql`(view_count >= 1) AND (view_count <= 2147483647)`,
    ),
    check("portal_release_states_view_timestamps_valid", sql`last_viewed_at >= first_opened_at`),
    check(
      "portal_release_states_guide_engagement_valid",
      sql`((guide_open_count = 0) AND (guide_opened_at IS NULL) AND (last_guide_opened_at IS NULL)) OR (((guide_open_count >= 1) AND (guide_open_count <= 2147483647)) AND (guide_opened_at IS NOT NULL) AND (last_guide_opened_at IS NOT NULL) AND (last_guide_opened_at >= guide_opened_at))`,
    ),
    check(
      "portal_release_states_dismiss_engagement_valid",
      sql`((dismiss_count = 0) AND (last_dismissed_at IS NULL)) OR (((dismiss_count >= 1) AND (dismiss_count <= 2147483647)) AND (last_dismissed_at IS NOT NULL))`,
    ),
  ],
);
